import OEMBED_PROVIDERS from"./constants.mjs";const globToRegExp=glob=>new RegExp(`^${glob.replace(/[-/\\^$+?.()|[\]{}]/g,"\\$&").replace(/\*/g,"[^/]*")}$`,"i");const doesURLMatch=(url,schemes)=>schemes.some(scheme=>globToRegExp(scheme).test(url));const normalizeUrl=function(){let url=arguments.length>0&&arguments[0]!==undefined?arguments[0]:"";return url.replace(/\/+$/,"").replace(/\{format\}/gi,"json")};const getOembedEndpointURL=function(url){let providers=arguments.length>1&&arguments[1]!==undefined?arguments[1]:OEMBED_PROVIDERS;let endpointURL;providers.forEach(provider=>{provider.endpoints.forEach(endpoint=>{if(!endpointURL&&doesURLMatch(url,endpoint.schemes)){endpointURL=endpoint.url}})});return normalizeUrl(endpointURL)};export default getOembedEndpointURL;